.login-container {
  width: 500px;

  @media screen and (max-width: 768px) {
    width: 500px;
  }

  @media screen and (max-width: 540px) {
    width: 360px;
  }
}


.hr-text {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    margin: 10px 0 20px;
    position: relative;
}

.hr-text::before,
.hr-text::after {
    content: '';
    flex-grow: 1;
    border-bottom: 1px solid #8b9197; /* Line color */
    margin: 0 10px;
    height: 0; /* Height should be 0 for a border-bottom to work */
}

.hr-text span {
    position: relative;
    padding: 0 10px;
    background-color: var(--card-background-color) !important; /* Match the card background */
    z-index: 2; /* Ensure the text stays above the line */
    color: rgb(var(--heading-text-color)) !important; /* Change the text color dynamically */
    font-size: 1rem;
}


/* Custom button styles */
#btnCredentials {
    background-color: var(--card-background-color) !important;
    border: 1px solid var(--bs-link-color) !important;
    color: var(--bs-link-color) !important;
    padding: 0.4rem 1rem;
    display: inline-flex;  /* Use flex to align icon and text */
    align-items: center;  /* Center content vertically */
    justify-content: center;  /* Center content horizontally */
    transition: all 0.3s ease !important;  /* Smooth transition for hover */
    transform: translateY(0) !important;  /* Ensure initial position */
}

/* Ensure the span inside the button has no independent hover effect */
#btnCredentials .btn-text {
    color: var(--bs-link-color) !important;
    font-size: 1rem;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: none !important;  /* Remove any border from the span */
    margin: 0;  /* Remove any margin from the span */
    pointer-events: none !important; /* Disable interaction on span */
    transition: none !important;  /* No transition effect */
}

/* Ensure the icon inside the button has no independent hover effect */
#btnCredentials .mdi {
    color: var(--bs-link-color) !important;
    border: none !important;  /* Remove any border from the icon */
    pointer-events: none !important; /* Disable interaction on icon */
    transition: none !important;  /* No transition effect */
}

/* Hover effect only on the button itself */
#btnCredentials:hover,
#btnCredentials:focus {
    background-color: var(--card-background-color) !important;
    border-color: var(--bs-link-color) !important;
    color: var(--bs-link-color) !important;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); /* Add subtle shadow */
    transform: translateY(-2px) !important;  /* Lift the entire button */
}

/* Prevent any independent transformations on span and icon */
#btnCredentials:hover .btn-text,
#btnCredentials:hover .mdi {
    color: var(--bs-link-color) !important;  /* Ensure color stays consistent */
    transform: none !important;  /* Prevent independent hover transformations */
    transition: none !important;  /* Disable transitions */
}

/* Custom button styles */
#btnUsernameless {
    background-color: var(--card-background-color) !important;
    border: 1px solid var(--bs-link-color) !important;
    color: var(--bs-link-color) !important;
    padding: 0.4rem 1rem;
    display: inline-flex;  /* Use flex to align icon and text */
    align-items: center;  /* Center content vertically */
    justify-content: center;  /* Center content horizontally */
    transition: all 0.3s ease !important;  /* Smooth transition for hover */
