    margin: 0;  /* Remove any margin from the span */
    pointer-events: none !important; /* Disable interaction on span */
    transition: none !important;  /* No transition effect */
}

/* Ensure the icon inside the button has no independent hover effect */
#btnUsernameless .mdi {
    color: var(--bs-link-color) !important;
    border: none !important;  /* Remove any border from the icon */
    pointer-events: none !important; /* Disable interaction on icon */
