        disableSubmitButtonUntilValid: true,
        validationSuccessClickHandler: function(status) {
            console.log("Validation status:", status);
            if (status === "success") {
                const agreeCheckBox = document.getElementById("agreeCheckBox");
                const submitButton = document.getElementById("validationSubmitButton");
                
                if (!agreeCheckBox) {
                    console.error("Element with ID 'agreeCheckBox' not found.");
                    return;
                }
                
                if (!submitButton) {
                    console.error("Element with ID 'validationSubmitButton' not found.");
                    return;
