    /********************************************************
    * COMPANY LOGO
    *********************************************************/
    --company-logo-img-url: url("https://avatars.githubusercontent.com/u/93611276?v=4");
    --company-logo-max-height: 95px;

    /********************************************************
    * PAGE BACKGROUND 
    *********************************************************/
    --background-image-url: url("");

    /********************************************************
    * CARD BODY
    *********************************************************/
    --card-background-color: rgb(242, 221, 184);
    --card-shadow-color: rgba(146, 55, 25, .35);

    /********************************************************
    * BODY
    *********************************************************/
    --body-font-family: Helvetica;
    --body-font-size: .8rem;

    /********************************************************
    * TEXT FONT COLORS
    *********************************************************/

    /*  PRIMARY FONT COLOR (RGB) */
    --text-color-primary: 181, 119, 87;

    /* HEADING FONT COLR (RBG) */
    --heading-text-color: 61, 69, 77;

    /*  MUTED TEXT ALPHA  */
    --text-color-muted-apha: 0.75;

    /*  ERROR FONT COLOR  */
    --text-color-error: rgb(185, 35, 32);

    /********************************************************
    * BUTTON ATTRIBUTES
    *********************************************************/

    /*  BUTTON FONT COLOR  */
    --button-primary-text-color: rgb(255, 255, 255);

    /*  BUTTON BACKGROUND COLOR (RGB)  */
    --button-primary-background-color: 146, 57, 23;

    /* LINK BUTTON FONT COLOR (RGB)  */
    --link-button-primary-color: 146, 23, 48;

    /* BUTTON BORDER RADIUS */
    --button-primary-border-radius: 20px;

    /*  BUTTON HOVER ALPHA  */
    --button-hover-alpha: 0.70;

    /*  BUTTON ACTIVE ALPHA  */
    --button-active-alpha: 0.80;

    /*  BUTTON DISABLED ALPHA  */
    --button-disabled-alpha: 0.65;

    /********************************************************
     * FORM CONTROLS
     *********************************************************/
    --form-control-border-radius: 20px;
    --card-body-border-radius: 25px;
    --focus-highlight-color: 105, 242, 121;

    /********************************************************
    * ACTIVITY INDICATOR & BUTTON SPINNER COLOR
    *********************************************************/

    --activity-indicator-color: rgb(207, 173, 126);

    --polling-indicator-color: rgb(237, 69, 69);

    /********************************************************
    * APPLYING TEXT COLOR - DO NOT CHANGE
    *********************************************************/
    /* H1,H2, H3, Body text color */
    --bs-body-color: rgb(var(--text-color-main)) !important;
    --bs-danger-rgb: var(--text-color-error);
