	const schema = {
  output: {
    type: "object",
    properties: {},
  },
};

devices.forEach(device => {
  if (device.status === "ACTIVE") {
    const propertyName = `nickname-${device.id}`;
    schema.output.properties[propertyName] = { type: "string" };
  }
});

