/*
 Update the devices array to include new properties 
 used when rendering the device list.
*/

// Titles and icons
const deviceTypes = {
	SMS: { title: "Text Message", icon: "mdi-comment-text-outline" },
	VOICE: { title: "Voice", icon: "mdi-face-agent" },
	EMAIL: { title: "Email", icon: "mdi-email-outline" },
	TOTP: { title: "Authenticator App", icon: "mdi-cellphone-key" },
	FIDO2: { title: "Passkey/FIDO2", icon: "mdi-fingerprint" },
	PLATFORM: { title: "Biometrics", icon: "mdi-fingerprint" },
	MOBILE: { title: "Mobile Push", icon: "mdi-account-key-outline" },
	SECURITY_KEY: { title: "Security Key", icon: "mdi-fingerprint" },
	MAGIC: { title: "Magic Link", icon: "mdi-auto-fix" }
}

// Device types that require masking
const SMS = "SMS";
const VOICE = "VOICE";
const EMAIL = "EMAIL";
const SEPARATOR = " - ";
const MAGIC = "Magic Link";

// Default passwordless allowed types
const defaultPasswordlessAllowedTypes = [
    "FIDO2",
    "PLATFORM",
    "MOBILE",
    "TOTP",
    "SECURITY_KEY"
];

// Main entry point
module.exports = a = async ({ params }) => {
	try {
		// Check if devices are passed in the params
		let devices = params.devices;
		let passwordlessAuth = params.passwordlessAuth;

		// If devices are not passed or empty, return an error
		if (!devices || devices.length === 0) {
			throw new Error("No devices available");
		}

		// If passwordlessAllowedTypes is empty, default to the predefined array
		let allowedTypes = params.passwordlessAllowedTypes && params.passwordlessAllowedTypes.length > 0 
			? params.passwordlessAllowedTypes 
			: defaultPasswordlessAllowedTypes;

		// Filter devices if passwordlessAuth is true
		if (passwordlessAuth === true) {
			devices = devices.filter(d => allowedTypes.includes(d.type));

			if (devices.length === 0) {
				return false;
			}
		}

		// Process each device
		for (const d of devices) {
			if (!d.type) {
				throw new Error("Device type is undefined for one of the devices");
			}

			// Mask phone and email where applicable
			if (d.type === SMS || d.type === VOICE) {
				if (!d.phone) throw new Error("Phone number missing for SMS/VOICE device");
				d.maskedValue = maskPhone(d.phone);
			} else if (d.type === EMAIL) {
				if (!d.email) throw new Error("Email missing for EMAIL device");
				d.maskedValue = maskEmail(d.email);
			}

			const nickname = d.nickname || "";
			const maskedValue = d.maskedValue || "";

			if (nickname && maskedValue) {
				d.displayText = `${nickname}${SEPARATOR}${maskedValue}`;
			} else if (!nickname && !maskedValue) {
				d.displayText = "";
			} else {
				d.displayText = `${nickname}${maskedValue}`;
			}

			// Assign Magic Link type
			if (d.nickname === MAGIC) {
				d.type = "MAGIC";
			}

			// Set the icon
			d.displayIcon = deviceTypes[d.type]?.icon || "mdi-help-circle-outline";
			// Set the device type title
			d.displayType = deviceTypes[d.type]?.title || "Unknown";
		}

		return { 'devices': devices };
	} catch (error) {
		console.error("Error processing devices:", error.message);
		return { error: error.message }; // Return error message in case of failure
	}
};

// Mask email
const maskEmail = (email) => {
	try {
		const [username, domain] = email.split("@");
		if (!username || !domain) throw new Error("Invalid email format");

		const maskedUsername =
			username.charAt(0) + "*".repeat(username.length - 2) + username.slice(-1);
		return maskedUsername + "@" + domain;
	} catch (error) {
		console.error("Error masking email:", error.message);
		return "Invalid email";
	}
};

// Mask phone number
const maskPhone = (phone) => {
	try {
		const numericPhoneNumber = phone.replace(/[^\d+]/g, "");
		if (numericPhoneNumber.length < 4) throw new Error("Invalid phone number format");

		// Mask the first six digits of the phone number
		const maskedPhoneNumber = "***-***-" + numericPhoneNumber.slice(-4);
		return maskedPhoneNumber;
	} catch (error) {
		console.error("Error masking phone:", error.message);
		return "Invalid phone number";
	}
};

