module.exports = a = async ({params}) => {

	// Function to replace values in a JSON object
	function replaceValue(obj, oldValue, newValue) {
		for (let key in obj) {
			if (obj.hasOwnProperty(key)) {
				if (typeof obj[key] === 'object' && obj[key] !== null) {
					// Recursively call for nested objects
					replaceValue(obj[key], oldValue, newValue);
				} else if (obj[key] === oldValue) {
					obj[key] = newValue;
				}
			}
		}
	}	

	const biographicMatchObject = params.metaDataEmbeddedObject.filter(metadata => metadata.provider === "BIOGRAPHIC_MATCHER");

	// Replace "NOT_APPLICABLE" with "ADDRESS_NOT_PROVIDED"
	replaceValue(biographicMatchObject, "NOT_APPLICABLE", "NOT_PROVIDED");

	return {'biographicMatchObject': biographicMatchObject}
}

