module.exports = a = async ({ params }) => {
    // Write code here
    console.log('params: ', JSON.stringify(params.biographicMatchObject, null, 2));

    // Check if biographicMatchObject is empty
    if (!Array.isArray(params.biographicMatchObject) || params.biographicMatchObject.length === 0) {
        console.log('biographicMatchObject is empty or not an array.');
        return;
    }

    console.log('biographicMatchObject is not empty. Processing entries...');

    // Iterate through the biographicMatchObject array and check match values
    const hasLowMatch = params.biographicMatchObject.some(obj =>
        obj.data.biographic_match_results.some(result => {
            console.log('Checking match value: ', result.match);
            return result.match === "LOW";
        })
    );

    console.log('hasLowMatch: ', hasLowMatch);

    // Return false if any match value is "LOW", otherwise return undefined
    if (hasLowMatch) {
        console.log('Found a match value that is "LOW". Returning false.');
        return false;
    } else {
        console.log('No match values are "LOW". Returning undefined.');
        return;
    }
};

